// Bundled seed media for the demo (App Review) sandbox world.
//
// The /media route serves these PNGs directly for `seed/...` keys, so the demo
// feed has photos without any R2 objects or real family content. Migration 0006
// inserts the seed posts/comments that reference these filenames. Generated by
// scripts/gen_seed.py — abstract gradients, never real photos.

const SEED_IMAGES: Record<string, string> = {
  'g1.png':
    '',
  'g2.png':
    '',
  'g3.png':
    '',
};

// Decode a bundled seed image to bytes, or null if the filename is unknown.
export function seedImage(filename: string): Uint8Array | null {
  const b64 = SEED_IMAGES[filename];
  if (!b64) return null;
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
